import {MAP_TYPES,createMap,validateMap,arrangeMap,renderMap,mapPDF} from './maps.mjs';
import {setting} from './db.mjs';
import {mapPersistence} from './maps-storage.mjs';
import {saveFile} from './exports.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
const copy=v=>structuredClone(v);

export async function mountMaps(root,{samples,toast}){
  let saved=await mapPersistence.load(),maps=[],activeId,selectedId,result,undo=[],redo=[],disposed=false,drag=null,zoom=1,saveSequence=0,saveStatus='Guardado en este dispositivo';
  if(!root.isConnected)return ()=>{};
  for(const item of saved?.maps||[]){try{maps.push({id:String(item.id),map:validateMap(item.map)});}catch{throw Error('No se pudo abrir un mapa guardado. Sus datos siguen conservados; no se reemplazaron.');}}
  if(!maps.length)maps=[{id:uid(),map:createMap('concept')}];
  activeId=maps.some(m=>m.id===saved?.activeId)?saved.activeId:maps[0].id;
  const current=()=>maps.find(m=>m.id===activeId).map;
  selectedId=current().nodes[0]?.id;
  const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)];
  const showSaved=()=>{if(!disposed&&$('#mapSaved'))$('#mapSaved').textContent=saveStatus;};
  const persist=()=>{const sequence=++saveSequence,{durable,done}=mapPersistence.save({version:1,activeId,maps});saveStatus=durable?'Guardado en este dispositivo':'Guardando…';showSaved();done.then(()=>{if(sequence===saveSequence){saveStatus='Guardado en este dispositivo';showSaved();}}).catch(e=>{if(sequence===saveSequence){saveStatus=durable?'Copia local guardada; pendiente de sincronizar':'No se pudo guardar';showSaved();if(!disposed)toast(durable?'Se conserva una copia local de tus mapas.':e.message);}});};
  const remember=()=>{undo.push(copy(current()));if(undo.length>40)undo.shift();redo=[];};
  const replace=m=>{maps.find(x=>x.id===activeId).map=m;};
  function edit(fn,{full=false}={}){const before=copy(current()),oldRedo=redo;try{fn(current());validateMap(current());undo.push(before);if(undo.length>40)undo.shift();redo=[];persist();full?draw():preview();}catch(e){replace(before);redo=oldRedo;toast(e.message);draw();}}
  function safe(fn){try{return fn();}catch(e){toast(e.message);}}
  function freeNode(map){const p=map.paper,width=Math.min(55,p.width-p.marginLeft-p.marginRight),height=24,top=p.marginTop+(map.title.trim()?Math.max(15,p.size/(72/25.4)*1.5+5):0);
    for(let y=top+2;y+height<=p.height-p.marginBottom;y+=5)for(let x=p.marginLeft;x+width<=p.width-p.marginRight;x+=5){if(!map.nodes.some(n=>x+width+3>n.x&&n.x+n.width+3>x&&y+height+3>n.y&&n.y+n.height+3>y))return {id:uid(),text:'Nueva idea',x,y,width,height,shape:'box',color:'#193c66',bold:false,italic:false};}
    throw Error('No queda un espacio libre para otra idea. Amplía la hoja o reduce los cuadros.');
  }
  function nodeOptions(value){return current().nodes.map((n,i)=>'<option value="'+esc(n.id)+'" '+(n.id===value?'selected':'')+'>'+(i+1)+'. '+esc(n.text.slice(0,45)||'Sin texto')+'</option>').join('');}
  const number=(label,key,value,min,max)=>'<label>'+label+'<input data-paper="'+key+'" type="number" min="'+min+'" max="'+max+'" step="1" value="'+value+'"></label>';
  function draw(){
    if(disposed||!root.isConnected)return;
    const m=current(),p=m.paper;
    root.innerHTML='<div class="map-toolbar card"><label>Mis mapas<select id="savedMap">'+maps.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===activeId?'selected':'')+'>'+esc(x.map.title||'Sin título')+'</option>').join('')+'</select></label><label>Nuevo mapa<select id="newMapType">'+MAP_TYPES.map(t=>'<option value="'+t.id+'">'+esc(t.label)+'</option>').join('')+'</select></label><button class="btn" id="createMap">+ Crear</button><button class="text-btn" id="copyMap">Duplicar</button><button class="text-btn" id="deleteMap">Eliminar mapa</button><div id="mapDeletePrompt" class="map-delete-prompt" role="alertdialog" aria-labelledby="mapDeleteTitle" aria-describedby="mapDeleteDescription" hidden><strong id="mapDeleteTitle">Eliminar mapa</strong><p id="mapDeleteDescription" class="fine">Se eliminará «'+esc(m.title||'Sin título')+'» de este dispositivo. Esta acción no se puede deshacer. Puedes guardar una copia editable antes de continuar.</p><div class="actions"><button class="btn" id="cancelDeleteMap">Conservar mapa</button><button class="btn" id="confirmDeleteMap">Eliminar definitivamente</button></div></div><span id="mapSaved" class="fine" role="status">'+esc(saveStatus)+'</span></div>'+
    '<div class="map-workspace"><section class="card map-controls"><label>Título del mapa<input id="mapTitle" maxlength="80" value="'+esc(m.title)+'"></label><div class="actions map-history"><button class="btn small" id="undoMap" '+(!undo.length?'disabled':'')+'>↶ Deshacer</button><button class="btn small" id="redoMap" '+(!redo.length?'disabled':'')+'>↷ Rehacer</button></div><div class="section-top spaced"><h2>Ideas</h2><button class="btn small" id="addNode">+ Idea</button></div><label>Idea seleccionada<select id="nodePicker">'+nodeOptions(selectedId)+'</select></label><div id="nodeInspector"></div><details class="paper-settings"><summary>Conexiones · '+m.edges.length+'</summary><div id="edgeList"></div><label>Desde<select id="edgeFrom">'+nodeOptions(selectedId)+'</select></label><label class="spaced">Hacia<select id="edgeTo">'+nodeOptions(m.nodes.find(n=>n.id!==selectedId)?.id)+'</select></label><label class="spaced">Texto de la conexión<input id="edgeLabel" maxlength="80" placeholder="por ejemplo: se divide en"></label><button class="btn spaced" id="addEdge">+ Conectar</button></details><details class="paper-settings"><summary>Organizar y personalizar hoja</summary><label class="spaced">Distribución<select id="mapType">'+MAP_TYPES.map(t=>'<option value="'+t.id+'" '+(m.type===t.id?'selected':'')+'>'+esc(t.label)+'</option>').join('')+'</select></label><button class="btn spaced" id="arrangeMap">Ordenar automáticamente</button><p class="fine spaced">Puedes arrastrar los cuadros en la hoja o indicar su posición en milímetros.</p><div class="fields">'+number('Ancho (mm)','width',p.width,70,420)+number('Alto (mm)','height',p.height,70,594)+number('Margen izquierdo','marginLeft',p.marginLeft,0,120)+number('Margen derecho','marginRight',p.marginRight,0,120)+number('Margen superior','marginTop',p.marginTop,0,120)+number('Margen inferior','marginBottom',p.marginBottom,0,120)+number('Letra (pt)','size',p.size,6,48)+number('Entre líneas (mm)','leading',p.leading,3,30)+'<label>Guías<select data-paper="ruling"><option value="none" '+(p.ruling==='none'?'selected':'')+'>Sin guías</option><option value="grid" '+(p.ruling==='grid'?'selected':'')+'>Cuadrícula</option><option value="lines" '+(p.ruling==='lines'?'selected':'')+'>Renglones</option></select></label>'+number('Cuadrícula (mm)','gridMm',p.gridMm,2,20)+'<label>Papel<input data-paper="paperColor" type="color" value="'+p.paperColor+'"></label><label>Guías<input data-paper="gridColor" type="color" value="'+p.gridColor+'"></label></div><button class="text-btn spaced" id="usePagePaper">Usar la hoja de Páginas</button></details><details class="paper-settings"><summary>Guardar copia o importar</summary><div class="actions"><button class="btn" id="exportMap">Copia editable</button><button class="btn" id="importMap">Importar mapa</button></div><input type="file" id="mapFile" accept=".trazomap,application/json" hidden><p class="fine spaced">La copia incluye ideas y conexiones; usa la biblioteca de letra activa al abrirla.</p></details></section>'+
    '<section class="map-preview"><div class="map-preview-top"><span class="pill">Tu letra real</span><span class="fine" id="mapDimensions"></span></div><div class="map-zoom" role="toolbar" aria-label="Ampliar mapa"><button class="btn small" id="zoomOut" aria-label="Alejar mapa">−</button><button class="btn small" id="zoomFit">Ajustar</button><button class="btn small" id="zoomIn" aria-label="Acercar mapa">+</button><span class="fine" id="zoomLabel">100 %</span></div><div id="mapCanvas" class="map-canvas" aria-label="Vista previa del mapa"></div><p class="fine spaced">Toca una idea para editarla. Arrastra para moverla.</p><p id="mapError" class="error" role="status"></p><div class="actions"><button class="btn primary" id="mapPdf">Descargar PDF</button><button class="btn" id="mapSvg">Descargar SVG</button></div><p class="fine spaced">Imprime al 100 % para conservar las medidas del papel.</p></section></div>';
    bind();inspector();edgeList();preview();
  }
  function inspector(){const n=current().nodes.find(x=>x.id===selectedId);if(!n){$('#nodeInspector').innerHTML='<p class="fine spaced">Añade una idea para empezar.</p>';return;}
    $('#nodeInspector').innerHTML='<label class="spaced">Texto de la idea<textarea id="nodeText" maxlength="500" rows="3">'+esc(n.text)+'</textarea></label><div class="format-toolbar"><button class="btn format-btn" id="nodeBold" aria-label="Idea en negrita" aria-pressed="'+!!n.bold+'"><b>B</b></button><button class="btn format-btn" id="nodeItalic" aria-label="Idea en cursiva" aria-pressed="'+!!n.italic+'"><i>I</i></button><label>Tinta<input id="nodeColor" type="color" value="'+n.color+'"></label></div><div class="fields"><label>Forma<select id="nodeShape">'+[['box','Cuadro'],['ellipse','Óvalo'],['diamond','Rombo']].map(([v,t])=>'<option value="'+v+'" '+(v===n.shape?'selected':'')+'>'+t+'</option>').join('')+'</select></label><button class="text-btn" id="removeNode">Eliminar idea</button>'+['x','y','width','height'].map((k,i)=>'<label>'+['Posición X (mm)','Posición Y (mm)','Ancho (mm)','Alto (mm)'][i]+'<input data-node-number="'+k+'" type="number" step="1" value="'+n[k]+'"></label>').join('')+'</div>';
    $('#nodeText').oninput=e=>edit(()=>{n.text=e.target.value;const option=$('#nodePicker').selectedOptions[0];if(option)option.textContent=n.text.slice(0,45)||'Sin texto';});
    for(const [id,key] of [['nodeBold','bold'],['nodeItalic','italic']])$('#'+id).onclick=()=>{edit(()=>n[key]=!n[key]);$('#'+id).setAttribute('aria-pressed',String(!!n[key]));};
    $('#nodeColor').oninput=e=>edit(()=>n.color=e.target.value);
    $('#nodeShape').onchange=e=>edit(()=>n.shape=e.target.value);
    $$('[data-node-number]').forEach(el=>el.onchange=()=>edit(()=>n[el.dataset.nodeNumber]=Number(el.value)));
    $('#removeNode').onclick=()=>edit(m=>{m.nodes=m.nodes.filter(x=>x.id!==n.id);m.edges=m.edges.filter(e=>e.from!==n.id&&e.to!==n.id);selectedId=m.nodes[0]?.id;},{full:true});
  }
  function edgeList(){const m=current();$('#edgeList').innerHTML=m.edges.length?m.edges.map((e,i)=>'<div class="map-edge"><p class="fine">'+esc(m.nodes.find(n=>n.id===e.from)?.text.slice(0,25))+' → '+esc(m.nodes.find(n=>n.id===e.to)?.text.slice(0,25))+'</p><label>Conexión '+(i+1)+'<input data-edge-label="'+esc(e.id)+'" maxlength="80" value="'+esc(e.label)+'"></label><button class="text-btn" data-remove-edge="'+esc(e.id)+'">Quitar conexión</button></div>').join(''):'<p class="fine spaced">Conecta dos ideas para expresar su relación.</p>';
    $$('[data-edge-label]').forEach(el=>el.oninput=()=>edit(()=>m.edges.find(e=>e.id===el.dataset.edgeLabel).label=el.value));
    $$('[data-remove-edge]').forEach(el=>el.onclick=()=>edit(()=>m.edges=m.edges.filter(e=>e.id!==el.dataset.removeEdge),{full:true}));
  }
  function preview(){if(disposed||!$('#mapCanvas'))return;result=null;$('#mapError').textContent='';$('#mapPdf').disabled=$('#mapSvg').disabled=true;$('#undoMap').disabled=!undo.length;$('#redoMap').disabled=!redo.length;
    try{result=renderMap(current(),samples);if(result.missing.length)throw Error('Faltan muestras para: '+result.missing.join(' ')+'. Añádelas en Mi letra.');$('#mapCanvas').innerHTML=result.svg;$('#mapDimensions').textContent=current().paper.width+' × '+current().paper.height+' mm';$('#mapPdf').disabled=$('#mapSvg').disabled=false;highlight();bindDrag();applyZoom();}
    catch(e){result=null;$('#mapCanvas').innerHTML='<div class="empty"><h3>Revisa este mapa</h3><p>Corrige el aviso o usa «Ordenar automáticamente» para ajustar las ideas.</p></div>';$('#mapError').textContent=e.message;}
  }
  function highlight(){$$('[data-node-id]').forEach(el=>{el.classList.toggle('map-selected',el.dataset.nodeId===selectedId);el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label','Editar idea: '+(current().nodes.find(n=>n.id===el.dataset.nodeId)?.text||''));el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(el.dataset.nodeId);}};});}
  function select(id){selectedId=id;$('#nodePicker').value=id;inspector();highlight();}
  function bindDrag(){const svg=$('#mapCanvas svg');if(!svg)return;
    svg.onpointerdown=e=>{const el=e.target.closest('[data-node-id]');if(!el)return;select(el.dataset.nodeId);const n=current().nodes.find(x=>x.id===selectedId),rect=svg.getBoundingClientRect();drag={pointer:e.pointerId,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,scaleX:current().paper.width/rect.width,scaleY:current().paper.height/rect.height,element:el,node:n,before:copy(current())};svg.setPointerCapture(e.pointerId);e.preventDefault();};
    svg.onpointermove=e=>{if(!drag||drag.pointer!==e.pointerId)return;const p=current().paper,dx=(e.clientX-drag.startX)*drag.scaleX,dy=(e.clientY-drag.startY)*drag.scaleY;drag.dx=Math.max(p.marginLeft,Math.min(p.width-p.marginRight-drag.node.width,drag.x+dx))-drag.x;drag.dy=Math.max(p.marginTop+(current().title.trim()?Math.max(15,p.size/(72/25.4)*1.5+5):0),Math.min(p.height-p.marginBottom-drag.node.height,drag.y+dy))-drag.y;drag.element.setAttribute('transform',`translate(${drag.dx} ${drag.dy})`);};
    const finish=e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag;drag=null;if(e.type!=='pointercancel'&&(Math.abs(d.dx||0)>.2||Math.abs(d.dy||0)>.2)){undo.push(d.before);if(undo.length>40)undo.shift();redo=[];d.node.x=Math.round((d.x+d.dx)*10)/10;d.node.y=Math.round((d.y+d.dy)*10)/10;persist();}inspector();preview();};svg.onpointerup=finish;svg.onpointercancel=finish;
  }
  function applyZoom(){const svg=$('#mapCanvas svg');if(svg)svg.style.width=(zoom*100)+'%';$('#zoomLabel').textContent=Math.round(zoom*100)+' %';$('#zoomOut').disabled=zoom<=1;$('#zoomIn').disabled=zoom>=4;}
  function bind(){
    $('#zoomIn').onclick=()=>{zoom=Math.min(4,zoom+.5);applyZoom();};$('#zoomOut').onclick=()=>{zoom=Math.max(1,zoom-.5);applyZoom();};$('#zoomFit').onclick=()=>{zoom=1;applyZoom();};
    $('#savedMap').onchange=e=>{activeId=e.target.value;selectedId=current().nodes[0]?.id;undo=[];redo=[];persist();draw();};
    const capacity=()=>{if(maps.length>=100)throw Error('Límite de 100 mapas. Guarda una copia y elimina un mapa para liberar espacio.');};
    $('#createMap').onclick=()=>safe(()=>{capacity();const m=createMap($('#newMapType').value);activeId=uid();maps.push({id:activeId,map:m});selectedId=m.nodes[0]?.id;undo=[];redo=[];persist();draw();});
    $('#copyMap').onclick=()=>safe(()=>{capacity();const m=copy(current());m.title=(m.title+' copia').slice(0,80);activeId=uid();maps.push({id:activeId,map:m});undo=[];redo=[];persist();draw();});
    $('#deleteMap').onclick=()=>{$('#mapDeletePrompt').hidden=false;$('#cancelDeleteMap').focus();};
    const cancelDelete=()=>{$('#mapDeletePrompt').hidden=true;$('#deleteMap').focus();};
    $('#cancelDeleteMap').onclick=cancelDelete;
    $('#mapDeletePrompt').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();cancelDelete();}};
    $('#confirmDeleteMap').onclick=()=>{const index=maps.findIndex(m=>m.id===activeId);maps.splice(index,1);if(!maps.length)maps.push({id:uid(),map:createMap('concept')});activeId=maps[Math.min(index,maps.length-1)].id;selectedId=current().nodes[0]?.id;undo=[];redo=[];persist();draw();$('#savedMap').focus();toast('Mapa eliminado.');};
    $('#mapTitle').oninput=e=>edit(m=>{m.title=e.target.value;$('#savedMap').selectedOptions[0].textContent=m.title||'Sin título';});
    $('#nodePicker').onchange=e=>select(e.target.value);
    $('#addNode').onclick=()=>safe(()=>{if(current().nodes.length>=60)throw Error('Este mapa admite hasta 60 ideas.');edit(m=>{const n=freeNode(m);m.nodes.push(n);selectedId=n.id;},{full:true});});
    $('#addEdge').onclick=()=>safe(()=>{const from=$('#edgeFrom').value,to=$('#edgeTo').value,label=$('#edgeLabel').value;if(!from||!to||from===to)throw Error('Elige dos ideas distintas.');if(current().edges.length>=120)throw Error('Límite de 120 conexiones.');if(current().edges.some(e=>e.from===from&&e.to===to))throw Error('Estas ideas ya están conectadas.');edit(m=>m.edges.push({id:uid(),from,to,label}),{full:true});});
    $('#arrangeMap').onclick=()=>safe(()=>{const arranged=arrangeMap({...current(),type:$('#mapType').value});remember();replace(arranged);persist();draw();});
    $('#mapType').onchange=e=>edit(m=>m.type=e.target.value);
    $$('[data-paper]').forEach(el=>el.onchange=()=>edit(m=>m.paper[el.dataset.paper]=el.type==='number'?Number(el.value):el.value));
    $('#usePagePaper').onclick=async()=>{const targetId=activeId;try{const p=await setting('draft',null);if(disposed||!root.isConnected||activeId!==targetId)return;if(!p){toast('Primero configura una hoja en Páginas.');return;}const next=copy(current());for(const k of ['width','height','margin','marginLeft','marginRight','marginTop','marginBottom','ruling','gridMm','gridOriginX','gridOriginY','gridColor','paperColor','size','leading','marginLine','marginLineX','marginLineColor','ink','seed'])if(p[k]!==undefined)next.paper[k]=p[k];const validated=validateMap(next);remember();replace(validated);persist();draw();}catch(e){if(!disposed)toast(e.message);}};
    $('#undoMap').onclick=()=>{if(!undo.length)return;redo.push(copy(current()));replace(undo.pop());selectedId=current().nodes.find(n=>n.id===selectedId)?.id||current().nodes[0]?.id;persist();draw();};
    $('#redoMap').onclick=()=>{if(!redo.length)return;undo.push(copy(current()));replace(redo.pop());selectedId=current().nodes.find(n=>n.id===selectedId)?.id||current().nodes[0]?.id;persist();draw();};
    const filename=()=>current().title.replace(/[^\p{L}\p{N}._ -]/gu,'_').slice(0,70)||'Mi-mapa';
    async function download(button,fn){button.disabled=true;try{await fn();toast('Archivo listo para guardar.');}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}}
    $('#mapPdf').onclick=e=>download(e.currentTarget,async()=>{if(!result)throw Error('Corrige el mapa antes de exportar.');const m=copy(current()),r=result;await saveFile(await mapPDF(r,m),filename()+'.pdf');});
    $('#mapSvg').onclick=e=>download(e.currentTarget,async()=>{if(!result)throw Error('Corrige el mapa antes de exportar.');await saveFile(new Blob([result.svg],{type:'image/svg+xml'}),filename()+'.svg');});
    $('#exportMap').onclick=e=>download(e.currentTarget,async()=>{const m=validateMap(current());await saveFile(new Blob([JSON.stringify({type:'trazo-map',version:1,map:m})],{type:'application/json'}),filename()+'.trazomap');});
    $('#importMap').onclick=()=>$('#mapFile').click();$('#mapFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2e6)throw Error('El mapa supera 2 MB.');capacity();const data=JSON.parse(await file.text());if(disposed||!root.isConnected)return;capacity();if(data.type!=='trazo-map'||data.version!==1)throw Error('Elige una copia .trazomap válida.');const m=validateMap(data.map);activeId=uid();maps.push({id:activeId,map:m});selectedId=m.nodes[0]?.id;undo=[];redo=[];persist();draw();toast('Mapa importado.');}catch(e){if(!disposed)toast(e.message);}};
  }
  const onPageHide=()=>{if(!disposed)persist();};
  window.addEventListener('pagehide',onPageHide);
  draw();persist();
  return ()=>{disposed=true;window.removeEventListener('pagehide',onPageHide);mapPersistence.flush();};
}
